cd /workspace/dataset
# Build a key containing all candidate Unicode-15.1 additions (sampled) and see which the ref escapes.
python3 - <<'PY' > /tmp/cands.txt 2>/dev/null || echo "no python3"
PY
node -e '
const cands = [];
// CJK Ext I block boundaries + samples
[0x2EBF0,0x2EBF1,0x2EC00,0x2ED00,0x2EE5C,0x2EE5D,0x2EE5E,0x2EE5F].forEach(c=>cands.push(c));
// other 15.1 additions
[0x31EF,0x2FFC,0x2FFD,0x2FFE,0x2FFF,0x2FFB].forEach(c=>cands.push(c));
const out=[];
for (const cp of cands) {
  const s = String.fromCodePoint(cp);
  const nodeNonPrintable = (cp!==0x20 && /\p{C}|\p{Z}/u.test(s));
  out.push([cp.toString(16), nodeNonPrintable?"ESC":"LIT", Buffer.from(s,"utf8").toString("hex")]);
}
console.log(out.map(r=>r.join(" ")).join("\n"));
' > /tmp/nodeverdict.txt
cat /tmp/nodeverdict.txt
echo "=== reference verdict per char ==="
while read hex verdict utf8hex; do
  key=$(printf "$(echo "$utf8hex" | sed 's/../\\x&/g')")
  res=$(./test16_executable --k1 "X${key}Y" --v1 1 --k2 b --v2 2 --k3 c --v3 3 2>&1 | head -1)
  case "$res" in *'\U'*|*'\u'*) ref=ESC;; *) ref=LIT;; esac
  flag=""; [ "$ref" != "$verdict" ] && flag="   <<< MISMATCH"
  echo "U+$hex node=$verdict ref=$ref$flag"
done < /tmp/nodeverdict.txt

