#!/usr/bin/env node
'use strict';
// Reference implementation written FROM the spec, used to validate the spec.
const fs = require('fs');
const PROG = 'test16_executable';
const SPEC = [
  { name: '--k1', dest: 'k1', type: 'str' },
  { name: '--v1', dest: 'v1', type: 'int' },
  { name: '--k2', dest: 'k2', type: 'str' },
  { name: '--v2', dest: 'v2', type: 'int' },
  { name: '--k3', dest: 'k3', type: 'str' },
  { name: '--v3', dest: 'v3', type: 'int' },
];
const OPTNAMES = ['-h', '--help', ...SPEC.map(s => s.name)];
const ABBREV_ORDER = ['--help', ...SPEC.map(s => s.name)]; // long options, declaration order

const HELP = `usage: ${PROG} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3\n` +
  `\noptions:\n  -h, --help  show this help message and exit\n` +
  `  --k1 K1\n  --v1 V1\n  --k2 K2\n  --v2 V2\n  --k3 K3\n  --v3 V3\n`;
const USAGE = `usage: ${PROG} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3`;

const OUT = [];
function emit(s) { OUT.push(s + '\n'); }
function flushOut() { if (OUT.length) fs.writeSync(1, OUT.join('')); }
function die2(msg) { fs.writeSync(2, USAGE + '\n' + PROG + ': error: ' + msg + '\n'); process.exit(2); }

// ---- pyRepr -------------------------------------------------------------
const FORCE_ESC = cp =>
  (cp >= 0x2EBF0 && cp <= 0x2EE5D) || cp === 0x31EF || (cp >= 0x2FFC && cp <= 0x2FFF);
function nonPrintable(cp) {
  if (cp === 0x20) return false;
  if (cp >= 0xD800 && cp <= 0xDFFF) return true;
  if (FORCE_ESC(cp)) return true;
  return /\p{C}|\p{Z}/u.test(String.fromCodePoint(cp));
}
function pyRepr(s) {
  const q = (s.includes("'") && !s.includes('"')) ? '"' : "'";
  let body = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') { body += '\\\\'; continue; }
    if (ch === q) { body += '\\' + ch; continue; }
    if (cp === 9) { body += '\\t'; continue; }
    if (cp === 10) { body += '\\n'; continue; }
    if (cp === 13) { body += '\\r'; continue; }
    if (nonPrintable(cp)) {
      if (cp < 0x100) body += '\\x' + cp.toString(16).padStart(2, '0');
      else if (cp < 0x10000) body += '\\u' + cp.toString(16).padStart(4, '0');
      else body += '\\U' + cp.toString(16).padStart(8, '0');
      continue;
    }
    body += ch;
  }
  return q + body + q;
}

// ---- pyInt --------------------------------------------------------------
const PY_WS = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,
  0x1680,0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200a,
  0x2028,0x2029,0x202f,0x205f,0x3000]);
const ND_BASES = (() => {
  const bases = [];
  for (let cp = 0; cp <= 0x10FFFF; cp++) {
    if (cp >= 0xD800 && cp <= 0xE000) continue;
    // cheap: only scan plausible ranges
  }
  return bases;
})();
function ndValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  const ch = String.fromCodePoint(cp);
  if (!/\p{Nd}/u.test(ch)) return -1;
  // find block start by walking back to the char whose value is 0
  let start = cp;
  while (start > 0 && /\p{Nd}/u.test(String.fromCodePoint(start - 1)) && (cp - start) < 9) start--;
  return cp - start;
}
function pyInt(raw) {
  const chars = [...raw];
  let i = 0, j = chars.length;
  while (i < j && PY_WS.has(chars[i].codePointAt(0))) i++;
  while (j > i && PY_WS.has(chars[j - 1].codePointAt(0))) j--;
  let body = chars.slice(i, j);
  if (body.length === 0) return null;
  let sign = 1n;
  if (body[0] === '+' || body[0] === '-') { if (body[0] === '-') sign = -1n; body = body.slice(1); }
  if (body.length === 0) return null;
  let digits = '';
  for (let k = 0; k < body.length; k++) {
    const ch = body[k];
    if (ch === '_') {
      if (k === 0 || k === body.length - 1) return null;
      if (body[k - 1] === '_') return null;
      if (ndValue(body[k - 1].codePointAt(0)) < 0) return null;
      if (ndValue(body[k + 1].codePointAt(0)) < 0) return null;
      continue;
    }
    const v = ndValue(ch.codePointAt(0));
    if (v < 0) return null;
    digits += String(v);
  }
  if (digits.length === 0) return null;
  if (digits.length > 4300) return null;
  return sign * BigInt(digits);
}

// ---- token classification ----------------------------------------------
const NEGNUM = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;
function resolveLong(tok) {
  // returns {name, explicit, sep} | 'unknown'
  const eq = tok.indexOf('=');
  const head = eq >= 0 ? tok.slice(0, eq) : tok;
  const explicit = eq >= 0 ? tok.slice(eq + 1) : null;
  if (OPTNAMES.includes(tok)) return { name: tok, explicit: null, sep: '' };
  if (eq >= 0 && OPTNAMES.includes(head)) return { name: head, explicit, sep: '=' };
  const target = eq >= 0 ? head : tok;
  const matches = ABBREV_ORDER.filter(n => n.startsWith(target) && n !== target);
  if (matches.length > 1) die2(`ambiguous option: ${tok} could match ${matches.join(', ')}`);
  if (matches.length === 1) return { name: matches[0], explicit, sep: eq >= 0 ? '=' : '' };
  return 'unknown';
}
function classify(tok) {
  if (tok === '') return { kind: 'A' };
  if (tok[0] !== '-') return { kind: 'A' };
  if (OPTNAMES.includes(tok)) return { kind: 'O', opt: { name: tok, explicit: null, sep: '' } };
  if (tok.length === 1) return { kind: 'A' };                       // bare "-"
  if (tok.startsWith('--')) {
    const r = resolveLong(tok);
    if (r !== 'unknown') return { kind: 'O', opt: r };
  } else {
    // single dash: try "-X" + concatenated tail
    const short = tok.slice(0, 2);
    if (OPTNAMES.includes(short)) return { kind: 'O', opt: { name: short, explicit: tok.slice(2), sep: '' } };
    const eq = tok.indexOf('=');
    if (eq >= 0 && OPTNAMES.includes(tok.slice(0, eq)))
      return { kind: 'O', opt: { name: tok.slice(0, eq), explicit: tok.slice(eq + 1), sep: '=' } };
  }
  if (NEGNUM.test(tok)) return { kind: 'A' };
  if (tok.includes(' ')) return { kind: 'A' };
  return { kind: 'U' };   // unknown option
}

// ---- parse --------------------------------------------------------------
const argv = process.argv.slice(2);
// Phase 1: prescan (surfaces ambiguity for EVERY token, even future values)
const cls = [];
let sawDD = false;
for (const tok of argv) {
  if (sawDD) { cls.push({ kind: 'A' }); continue; }
  if (tok === '--') { cls.push({ kind: 'DD' }); sawDD = true; continue; }
  cls.push(classify(tok));
}
// Phase 2: consume left-to-right
const vals = {};
const extras = [];
for (let i = 0; i < argv.length; i++) {
  const c = cls[i];
  if (c.kind === 'A' || c.kind === 'U' || c.kind === 'DD') { extras.push(argv[i]); continue; }
  let { name, explicit, sep } = c.opt;
  for (;;) {
    if (name === '-h' || name === '--help') {
      if (explicit !== null) {
        if (sep === '=' || explicit === '')
          die2(`argument -h/--help: ignored explicit argument ${pyRepr(explicit)}`);
        // single-dash bundling: take help action now
        fs.writeSync(1, HELP); process.exit(0);
      }
      fs.writeSync(1, HELP); process.exit(0);
    }
    const s = SPEC.find(x => x.name === name);
    let raw;
    if (explicit !== null) raw = explicit;
    else {
      if (i + 1 >= argv.length || cls[i + 1].kind !== 'A')
        die2(`argument ${name}: expected one argument`);
      raw = argv[++i];
    }
    if (s.type === 'int') {
      const n = pyInt(raw);
      if (n === null) die2(`argument ${name}: invalid int value: ${pyRepr(raw)}`);
      vals[s.dest] = n;
    } else vals[s.dest] = raw;
    break;
  }
}
const missing = SPEC.filter(s => !(s.dest in vals)).map(s => s.name);
if (missing.length) die2('the following arguments are required: ' + missing.join(', '));
if (extras.length) die2('unrecognized arguments: ' + extras.join(' '));

// ---- bidict -------------------------------------------------------------
function reprMap(m) {
  if (m.size === 0) return 'bidict()';
  return 'bidict({' + [...m].map(([k, v]) => pyRepr(k) + ': ' + String(v)).join(', ') + '})';
}
const PYI = `[PYI-${process.pid}:ERROR] Failed to execute script 'test16' due to unhandled exception!`;
function tb14(exc) {
  return 'Traceback (most recent call last):\n' +
    '  File "test16.py", line 14, in <module>\n' +
    '    b = bidict({args.k1: args.v1, args.k2: args.v2})\n' +
    '        ' + '^'.repeat(44) + '\n' +
    '  File "bidict/_base.py", line 161, in __init__\n' +
    '  File "bidict/_base.py", line 454, in _update\n' +
    '  File "bidict/_base.py", line 347, in _dedup\n' + exc + '\n' + PYI + '\n';
}
function tb16(dedupLine, exc) {
  return 'Traceback (most recent call last):\n' +
    '  File "test16.py", line 16, in <module>\n' +
    '    b[args.k3] = args.v3\n' +
    '    ~^^^^^^^^^\n' +
    '  File "bidict/_bidict.py", line 80, in __setitem__\n' +
    '  File "bidict/_bidict.py", line 106, in put\n' +
    '  File "bidict/_base.py", line 454, in _update\n' +
    `  File "bidict/_base.py", line ${dedupLine}, in _dedup\n` + exc + '\n' + PYI + '\n';
}
function fail(tbText) { fs.writeSync(2, tbText); flushOut(); process.exit(1); }

// Step A: python dict literal
const lit = new Map();
lit.set(vals.k1, vals.v1);
lit.set(vals.k2, vals.v2);
// Step B: bidict() constructor -> reject duplicate values
{
  const seen = new Map();
  for (const [k, v] of lit) {
    const key = String(v);
    if (seen.has(key)) fail(tb14('bidict.ValueDuplicationError: ' + String(v)));
    seen.set(key, k);
  }
}
const b = lit;
emit(reprMap(b));                                    // line 15
// Step D: b[k3] = v3
{
  const keys = [...b.keys()];
  const ki = keys.indexOf(vals.k3);
  const vi = keys.findIndex(k => b.get(k) === vals.v3);
  if (ki >= 0 && vi >= 0) {
    if (ki !== vi)
      fail(tb16(333, `bidict.KeyAndValueDuplicationError: (${pyRepr(vals.k3)}, ${String(vals.v3)})`));
    // else no-op
  } else if (ki < 0 && vi >= 0) {
    fail(tb16(347, 'bidict.ValueDuplicationError: ' + String(vals.v3)));
  } else {
    b.set(vals.k3, vals.v3);
  }
}
emit(reprMap(b));                                    // line 17
b.clear();
emit(reprMap(b));                                    // line 19
b.set('new', 100n);
emit(reprMap(b));                                    // line 23
flushOut();
process.exitCode = 0;

